API Gateway / Payment Gateway Integratio.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("API Gateway / Payment Gateway Integration Container", "API Gateway / Payment Gateway Integration Container") {
    Component(Request_Router, "Request Router", "AWS ECS with Fargate", "Receives incoming authorization requests and routes them for processing.")
    Component(Proxy_Coordinator, "Proxy Coordinator", "AWS ECS with Fargate", "Coordinates PAN scrubbing and tokenization requests.")
    Component(Scoring_Invoker, "Scoring Invoker", "AWS ECS with Fargate", "Queries real-time fraud scores for transactions.")
}

Rel(Request_Router, Proxy_Coordinator, "Forwards requests for PAN scrubbing", "Internal API")
Rel(Request_Router, Scoring_Invoker, "Queries fraud scores", "gRPC/REST")
@enduml

Model & Rule Registry Service Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(model_and_rule_registry_service_container, "Model & Rule Registry Service Container") {
    Component(Model and Rule API Controller, "Model and Rule API Controller", "AWS ECS / Fargate, REST/gRPC", "Receives requests to register, update, and query fraud detection models and rules.")
    Component(Registry Orchestrator Service, "Registry Orchestrator Service", "Python / Node.js", "Manages the business logic for publishing immutable models and rules to downstream engines.")
    Component(Publisher Service, "Publisher Service", "Amazon SNS / SQS", "Broadcasts immutable models and rules asynchronously to the scoring and case management engines.")
}

Rel(Model and Rule API Controller, Registry Orchestrator Service, "Forwards registration and query requests")
Rel(Registry Orchestrator Service, Publisher Service, "Triggers broadcast of immutable models and rules")
@enduml

Audit & Compliance Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Audit_Compliance_Container", "Audit & Compliance Container") {
    Component("Audit_Consumer_Component", "Audit Consumer Component", "AWS ECS with Fargate / AWS SDK", "Consumes decision payloads and audit events asynchronously from Amazon SQS / SNS.")
    Component("Compliance_Logger_Component", "Compliance Logger Component", "AWS ECS with Fargate / AWS SDK", "Processes and formats audit records for tamper-evident compliance storage.")
}

Rel("Audit_Consumer_Component", "Compliance_Logger_Component", "Passes decision payloads for compliance logging")

@enduml

