Amazon SQS / SNS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(real_time_scoring_engine_container, "Real-Time Scoring Engine Container", "AWS ECS with Fargate")
System_Ext(audit_compliance_container, "Audit & Compliance Container", "AWS ECS with Fargate")

Container_Boundary(amazon_sqs_sns, "Amazon SQS / SNS") {
    Component(sqs_fifo_queues, "SQS FIFO Queues", "Amazon SQS FIFO", "Decouples the asynchronous audit trail from the synchronous payment path using FIFO queues, DLQs, and KMS encryption.")
    Component(sns_topics, "SNS Topics", "Amazon SNS", "Publishes scoring decisions asynchronously using AWS SDK to downstream compliance consumers.")
}

Rel(real_time_scoring_engine_container, sqs_fifo_queues, "Publishes scoring decisions asynchronously using AWS SDK", "")
Rel(sqs_fifo_queues, audit_compliance_container, "Supplies decoupled audit messages via SQS Consumer", "")
@enduml

Amazon S3 Object Lock.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Amazon S3 Object Lock", "Amazon S3 Object Lock") {
    Component("WORM Storage Engine", "WORM Storage Engine", "Amazon S3 Object Lock (Compliance Mode)", "Provides immutable, Write-Once-Read-Many (WORM) storage for tamper-evident audit logs enforcing a 7-year retention mandate.")
    Component("Lifecycle and Archival Manager", "Lifecycle and Archival Manager", "Amazon S3 Glacier Lifecycle Policies", "Automatically transitions audit logs to Glacier Flexible Archive to meet the monthly budget constraint.")
}

Rel("Audit & Compliance Container", "WORM Storage Engine", "Writes tamper-evident audit logs with client-side SHA-256 hashes and schema versions", "AWS SDK")
Rel("WORM Storage Engine", "Lifecycle and Archival Manager", "Transitions older log data for long-term retention", "")

@enduml
